'use strict';
// ISOLATED_TEST only: fresh test verification key/registry/package generated by
// tests, never accepted by production composition or production trust anchors.
const fs=require('node:fs/promises');
const {createComposition:base}=require('./rulekit-test-composition');
const {TrustedRegistry}=require('../../../d4-rulekit/snapshot-management/src/trust');
const {SnapshotManager}=require('../../../d4-rulekit/snapshot-management/src/manager');
const {strategies}=require('../../../d4-rulekit/snapshot-management/tests/helpers');
async function createComposition(env){
 const config=JSON.parse(await fs.readFile(env.TEST_SNAPSHOT_CONFIG,'utf8'));
 const registry=new TrustedRegistry({anchors:config.anchors,ruleKitVersion:'test-rulekit/v1',scope:'ISOLATED_TEST'});
 const manager=new SnapshotManager({dataRoot:config.dataRoot,registry,strategies,workerGeneration:Number(env.D4_RULEKIT_WORKER_GENERATION)});await manager.start();
 const composition=await base(env);
 const original=composition.application.createSession.bind(composition.application);
 composition.application.createSession=async options=>{
  const active=await manager.getActive();
  if(!active.active || options.snapshotId!==active.active.snapshotId || options.snapshotManifestSha256!==active.active.manifestSha256)throw Object.assign(new Error('synthetic profile binding mismatch'),{code:'SNAPSHOT_MISMATCH'});
  return original(options);
 };
 return {...composition,snapshotManagement:manager,close:()=>manager.close()};
}
module.exports={createComposition};
